// ??4?$vector@VAsciiString@@V?$allocator@VAsciiString@@@_STL@@@_STL@@QAEAAV01@ABV01@@Z
// partial score=0.95 date=2026-09-27
// cl: /DNDEBUG /MD /EHsc
// stlport
// STLport vector<AsciiString>::operator= for retail 0x000DE2C0. Byte-exact
// (212/212) under the scoped gate except ONE relocation: the call at +0x3a.
// The body is the STLport 5 assignment from stl/_vector.c -- three branches,
// _M_allocate_and_copy / __copy+_Destroy / __copy+__uninitialized_copy, then
// _M_finish = _M_start + x.size().
//
// ELEMENT TYPE PROVEN, not guessed: all four remaining out-of-line helpers
// operate on 4-byte elements through BFME retail AsciiString members --
// 0x00063080 _Destroy calls ??1AsciiString@@, 0x000D0EB0 constructs through the
// AsciiString copy constructor, 0x000DDFB0 copy-assigns through
// UnicodeString::set, 0x000DE0E0 allocates count*4 and copy-constructs.
// /D_STLP_USE_STATIC_LIB changes nothing here (the allocation is out of line).
//
// OPEN BLOCKER (blocker=callee): retail calls the ILT thunk 0x0003588C ->
// 0x000630B0, but the only pin for
//   ?_M_clear@?$vector@VAsciiString@@V?$allocator@VAsciiString@@@_STL@@@_STL@@IAEXXZ
// is 0x0001C9B8 -> 0x007578F0, and pin_consistency refuses a second pin
// (divergent-bodies: at most one pin names a symbol with two different bodies).
// The existing pin is the misidentified half: 0x007578F0 and 0x000630B0 are
// 81 bytes and identical except for the element destructor -- 0x000630B0
// calls ??1BFMERetailAsciiString@@ (0x0000D828 -> ??1AsciiString@@) while
// 0x007578F0 calls ??1BfmeHandleCX@@ (0x00030652), so 0x000630B0 is the
// AsciiString one and 0x007578F0 belongs to vector<BfmeHandleCX>.
// 0x0003588C is the majority call site (0x000637EA, 0x00065834, 0x000DE2FA);
// 0x0001C9B8 has exactly one referrer, 0x000757D5A inside the matched row
// 0x00757C70 _M_insert_overflow<vector<AsciiString>> (row 24313,
// game/GameEngine/Source/Common/AsciiStringVectorInsert.cpp), which itself
// allocates through __new_alloc::allocate/operator new while its callee
// 0x007578F0 deallocates through __node_alloc -- a config mix that pin also
// contradicts. Landing this body therefore needs that row retitled to
// vector<BfmeHandleCX> first: shared state outside this body.

#include <new>
#include "ascii_string.h"
#include <vector>

void ForceAsciiStringVectorAssign(_STL::vector<AsciiString> &dst,
	const _STL::vector<AsciiString> &src)
{
	dst = src;
}
